sys_ux_client_script.script:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
* @param {ApiHelpers} params.helpers
*/
function handler({api, event, helpers, imports}) {
    var infoPayload = JSON.parse(api.data.get_ops_user_data_1.output);
    var designation = infoPayload.designation;

    if (designation == "Senior Manager" || designation == "Manager" || designation == "Security Admin" || designation == "Admin")
        api.setState('showStatsTab', false);
    else
        api.setState('showStatsTab', true);

    if (designation == "Senior Manager" || designation == "Manager" || designation == "Senior Associate" || designation == "Security Admin" || designation == "Admin")
        api.setState('showTasksTab', false);
    else
        api.setState('showTasksTab', true);
}
